package escuela.personal.controller;
import escuela.personal.dto.*;import escuela.personal.service.*;import escuela.admin.dto.*;import escuela.admin.support.MensajeErrorFormulario;
import escuela.common.exception.ReglaNegocioException;import lombok.RequiredArgsConstructor;import jakarta.validation.Valid;import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import org.springframework.http.*;
import java.util.*;import java.io.*;import org.springframework.web.util.UriComponentsBuilder;

@Controller @RequiredArgsConstructor
public class OrganizacionLaboralController {
 private final OrganizacionLaboralService service;private final EmpleadoService empleados;private final CondicionesSalarialesService salarios;
 private void base(String tipo,FiltroOrganizacionLaboral original,FiltrosCatalogosPersonal selecciones,Model m){
  service.prepararFiltros(selecciones);m.addAttribute("selecciones",selecciones);
  var p=empleados.autorizarSalarios(false);var f=original.normalizado(tipo.equals("asignaciones"));var modulo=switch(tipo){case "jornadas"->ModuloCatalogo.JORNADAS_LABORALES;case "esquemas"->ModuloCatalogo.ESQUEMAS_REMUNERACION;default->ModuloCatalogo.ASIGNACIONES_LABORALES;};
  var permisos=p.authorities().stream().map(x->x.getAuthority()).collect(java.util.stream.Collectors.toSet());m.addAttribute("modulos",Arrays.stream(ModuloCatalogo.values()).filter(x->x.visibleCon(permisos)).toList());m.addAttribute("moduloActual",modulo);m.addAttribute("titulo",modulo.titulo());m.addAttribute("tipo",tipo);m.addAttribute("filtro",f);m.addAttribute("volverUrl",url("/admin/"+tipo,f,selecciones));m.addAttribute("puedeEditar",empleados.permitido("CONDICION_SALARIAL_ADMINISTRAR"));m.addAttribute("moneda",service.moneda());m.addAttribute("empleadoFiltro",f.empleadoTexto());if(tipo.equals("asignaciones")&&f.empleadoId()!=null){var e=empleados.obtener(f.empleadoId());m.addAttribute("empleadoFiltro",e.codigo()+" · "+e.nombre());}
 }
 private String url(String ruta,FiltroOrganizacionLaboral original,FiltrosCatalogosPersonal selecciones){var f=original.normalizado(ruta.contains("asignaciones"));return selecciones.agregarA(UriComponentsBuilder.fromPath(ruta).queryParam("q",f.q()).queryParam("estado",f.estado()).queryParam("pagina",f.pagina()).queryParam("tamanio",f.tamanio()).queryParamIfPresent("empleadoId",Optional.ofNullable(f.empleadoId())).queryParamIfPresent("desde",Optional.ofNullable(f.desde())).queryParamIfPresent("hasta",Optional.ofNullable(f.hasta()))).build().encode().toUriString();}
 @GetMapping("/admin/{tipo:jornadas|esquemas}")String catalogo(@PathVariable String tipo,@ModelAttribute FiltroOrganizacionLaboral filtro,@ModelAttribute("selecciones")FiltrosCatalogosPersonal selecciones,Model m){base(tipo,filtro,selecciones,m);var f=(FiltroOrganizacionLaboral)m.getAttribute("filtro");try{m.addAttribute("resultado",service.listar(tipo,f.q(),f.estado(),f.pagina(),f.tamanio(),selecciones));}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());m.addAttribute("resultado",org.springframework.data.domain.Page.empty());}return "admin/laboral-catalogo";}
 @GetMapping("/admin/{tipo:jornadas|esquemas}/nuevo")String nuevo(@PathVariable String tipo,@ModelAttribute FiltroOrganizacionLaboral filtro,@ModelAttribute("selecciones")FiltrosCatalogosPersonal selecciones,Model m){empleados.autorizarSalarios(true);base(tipo,filtro,selecciones,m);m.addAttribute("form",new ConfiguracionLaboralForm());return "admin/laboral-catalogo-form";}
 @GetMapping("/admin/{tipo:jornadas|esquemas}/{id}/editar")String editar(@PathVariable String tipo,@PathVariable Long id,@ModelAttribute FiltroOrganizacionLaboral filtro,@ModelAttribute("selecciones")FiltrosCatalogosPersonal selecciones,Model m){empleados.autorizarSalarios(true);var c=service.obtener(tipo,id);var f=new ConfiguracionLaboralForm();f.setCodigo(c.codigo());f.setNombre(c.nombre());f.setDescripcion(c.descripcion());f.setActivo(c.activo());f.setVersion(c.version());f.setHorasSemanales(c.horas());f.setPuestoId(c.puestoId());f.setPuestoTexto(c.puestoTexto());f.setJornadaId(c.jornadaId());f.setJornadaTexto(c.jornadaTexto());f.setImporteBruto(c.importe());f.setBase(c.base());f.setFrecuencia(c.frecuencia());base(tipo,filtro,selecciones,m);m.addAttribute("form",f);m.addAttribute("registroId",id);return "admin/laboral-catalogo-form";}
 @PostMapping("/admin/{tipo:jornadas|esquemas}")String guardar(@PathVariable String tipo,@RequestParam(required=false)Long id,@Valid @ModelAttribute("form")ConfiguracionLaboralForm form,BindingResult errores,@ModelAttribute FiltroOrganizacionLaboral filtro,@ModelAttribute("selecciones")FiltrosCatalogosPersonal selecciones,Model m,RedirectAttributes flash){empleados.autorizarSalarios(true);if(id!=null)service.obtener(tipo,id);if(!errores.hasErrors())try{service.guardar(tipo,id,form);flash.addFlashAttribute("mensaje","Catálogo guardado; las asignaciones anteriores conservan su configuración autorizada.");return "redirect:"+url("/admin/"+tipo,filtro,selecciones);}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}if(errores.hasErrors())m.addAttribute("errorOperacion","Completa los campos obligatorios y revisa los formatos indicados.");base(tipo,filtro,selecciones,m);m.addAttribute("registroId",id);return "admin/laboral-catalogo-form";}
 @GetMapping("/admin/{tipo:jornadas|esquemas}/buscar")@ResponseBody ResponseEntity<ResultadoAutocompletado> buscar(@PathVariable String tipo,@RequestParam(defaultValue="")String q){var filas=service.buscar(tipo,q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(filas.stream().map(x->new OpcionAutocompletado(x.id(),x.codigo()+" · "+x.nombre(),x.horas()+" horas semanales")).toList(),false));}
 @GetMapping("/admin/personal/filtros/{tipo:puestos|jornadas|esquemas}/buscar")@ResponseBody ResponseEntity<ResultadoAutocompletado> filtros(@PathVariable String tipo,@RequestParam(defaultValue="")String q){var filas=service.buscarFiltros(tipo,q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(filas.stream().limit(10).toList(),filas.size()>10));}
 @GetMapping("/admin/asignaciones/empleados/buscar")@ResponseBody ResponseEntity<ResultadoAutocompletado> empleados(@RequestParam(defaultValue="")String q){var filas=service.buscarEmpleados(q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(filas.stream().limit(10).toList(),filas.size()>10));}
 @GetMapping("/admin/asignaciones/contexto")@ResponseBody ResponseEntity<OrganizacionLaboralService.Contexto> contexto(@RequestParam Long empleadoId,@RequestParam Long esquemaId){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(service.contexto(empleadoId,esquemaId));}
 @GetMapping("/admin/asignaciones")String asignaciones(@ModelAttribute FiltroOrganizacionLaboral filtro,@ModelAttribute("selecciones")FiltrosCatalogosPersonal selecciones,Model m){base("asignaciones",filtro,selecciones,m);var f=(FiltroOrganizacionLaboral)m.getAttribute("filtro");try{f.validarSeleccion();m.addAttribute("resultado",service.asignaciones(f.empleadoId(),f.q(),f.estado(),f.desde(),f.hasta(),f.pagina(),f.tamanio(),selecciones));}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());m.addAttribute("resultado",org.springframework.data.domain.Page.empty());}return "admin/laboral-asignaciones";}
 @GetMapping("/admin/asignaciones/nuevo")String nuevaAsignacion(@ModelAttribute FiltroOrganizacionLaboral filtro,@ModelAttribute("selecciones")FiltrosCatalogosPersonal selecciones,Model m){empleados.autorizarSalarios(true);base("asignaciones",filtro,selecciones,m);var f=new AsignacionLaboralForm();f.setInicio(service.hoy());if(filtro.empleadoId()!=null){var e=empleados.obtener(filtro.empleadoId());f.setEmpleadoId(e.id());f.setEmpleadoTexto(e.codigo()+" · "+e.nombre());}m.addAttribute("form",f);return "admin/laboral-asignacion-form";}
 @PostMapping("/admin/asignaciones")String asignar(@Valid @ModelAttribute("form")AsignacionLaboralForm form,BindingResult errores,@ModelAttribute FiltroOrganizacionLaboral filtro,@ModelAttribute("selecciones")FiltrosCatalogosPersonal selecciones,Model m,RedirectAttributes flash){empleados.autorizarSalarios(true);if(!errores.hasErrors())try{service.asignar(form);flash.addFlashAttribute("mensaje","Asignación registrada con su configuración histórica; no se generó nómina ni movimientos de dinero.");return "redirect:"+url("/admin/asignaciones",filtro,selecciones);}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}if(errores.hasErrors())m.addAttribute("errorOperacion","Selecciona empleado y configuración de puesto y sueldo, espera su consulta y completa vigencia y motivo antes de confirmar.");base("asignaciones",filtro,selecciones,m);return "admin/laboral-asignacion-form";}
 @GetMapping("/admin/asignaciones/{id:\\d+}")String detalle(@PathVariable Long id,@ModelAttribute FiltroOrganizacionLaboral filtro,@ModelAttribute("selecciones")FiltrosCatalogosPersonal selecciones,@RequestParam(defaultValue="0")int paginaHistorial,Model m){base("asignaciones",filtro,selecciones,m);var a=service.asignacion(id);m.addAttribute("asignacion",a);m.addAttribute("historial",salarios.historial(a.empleadoId(),paginaHistorial));return "admin/laboral-asignacion-detalle";}
 @PostMapping("/admin/asignaciones/{id:\\d+}/cancelar")String cancelar(@PathVariable Long id,@RequestParam Long version,@RequestParam String motivo,@ModelAttribute FiltroOrganizacionLaboral filtro,@ModelAttribute("selecciones")FiltrosCatalogosPersonal selecciones,RedirectAttributes flash){empleados.autorizarSalarios(true);try{service.cancelar(id,version,motivo);flash.addFlashAttribute("mensaje","Programación cancelada; vigencia anterior restaurada cuando corresponde. Sin movimientos financieros.");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){flash.addFlashAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}return "redirect:"+url("/admin/asignaciones/"+id,filtro,selecciones);}
 @GetMapping("/admin/{tipo:jornadas|esquemas|asignaciones}/excel")void excel(@PathVariable String tipo,@ModelAttribute FiltroOrganizacionLaboral original,@ModelAttribute("selecciones")FiltrosCatalogosPersonal selecciones,HttpServletResponse r)throws IOException{
  empleados.autorizarSalarios(false);var f=original.normalizado(tipo.equals("asignaciones"));if(tipo.equals("asignaciones"))f.validarSeleccion();
  // Ejecutar la consulta autorizada antes de abrir el flujo binario.
  if(tipo.equals("asignaciones"))service.asignaciones(f.empleadoId(),f.q(),f.estado(),f.desde(),f.hasta(),0,100,selecciones);else service.listar(tipo,f.q(),f.estado(),0,100,selecciones);
  r.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");r.setHeader("Content-Disposition","attachment; filename="+tipo+".xlsx");r.setHeader("Cache-Control","no-store");
  try(var book=new org.apache.poi.xssf.streaming.SXSSFWorkbook(100)){try{var sheet=book.createSheet("Personal");String[] cab=tipo.equals("asignaciones")?new String[]{"Empleado","Código laboral","Puesto histórico","Configuración histórica","Jornada histórica","Horas semanales","Sueldo bruto","Moneda","Base","Frecuencia","Inicio","Fin","Estado","Motivo"}:tipo.equals("jornadas")?new String[]{"Código","Nombre","Horas semanales","Descripción","Estado"}:new String[]{"Código","Nombre","Puesto","Jornada","Horas semanales","Sueldo bruto","Moneda","Base","Frecuencia","Descripción","Estado"};var h=sheet.createRow(0);for(int n=0;n<cab.length;n++){h.createCell(n).setCellValue(cab[n]);sheet.setColumnWidth(n,28*256);}int fila=1,pagina=0;boolean mas;
   do{if(tipo.equals("asignaciones")){var page=service.asignaciones(f.empleadoId(),f.q(),f.estado(),f.desde(),f.hasta(),pagina++,100,selecciones);mas=page.hasNext();for(var a:page)escribir(sheet.createRow(fila++),new Object[]{a.empleado(),a.codigoEmpleado(),a.puesto(),a.esquema(),a.jornada(),a.horas(),a.importe(),a.moneda(),a.base(),a.frecuencia(),fecha(a.inicio()),fecha(a.fin()),a.estado(),a.motivo()});}else{var page=service.listar(tipo,f.q(),f.estado(),pagina++,100,selecciones);mas=page.hasNext();for(var c:page)escribir(sheet.createRow(fila++),tipo.equals("jornadas")?new Object[]{c.codigo(),c.nombre(),c.horas(),c.descripcion(),c.activo()?"Activo":"Inactivo"}:new Object[]{c.codigo(),c.nombre(),c.puestoTexto(),c.jornadaTexto(),c.horas(),c.importe(),c.moneda(),c.base(),c.frecuencia(),c.descripcion(),c.activo()?"Activo":"Inactivo"});}}while(mas);
   sheet.createFreezePane(0,1);sheet.setAutoFilter(new org.apache.poi.ss.util.CellRangeAddress(0,Math.max(0,fila-1),0,cab.length-1));book.write(r.getOutputStream());
  }finally{book.dispose();}}
 }
 private static void escribir(org.apache.poi.ss.usermodel.Row row,Object[] values){for(int i=0;i<values.length;i++){var cell=row.createCell(i);if(values[i] instanceof Number n)cell.setCellValue(n.doubleValue());else cell.setCellValue(values[i]==null?"":values[i].toString());}}
 private static String fecha(java.time.LocalDate f){return f==null?"Sin fecha de fin":f.format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy"));}
}
